{
  "flashcards": [
    {
      "front": "How do you identify slow queries in PostgreSQL?",
      "back": "Use `pg_stat_statements` to track execution statistics, analyze `EXPLAIN ANALYZE` output to inspect query plans, and monitor `pg_stat_activity` for long-running transactions or locks.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the primary benefit of using gRPC over REST for internal microservices?",
      "back": "gRPC uses Protocol Buffers for efficient binary serialization and HTTP/2 for multiplexing, resulting in lower latency, smaller payload sizes, and strict contract enforcement via generated code.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you handle database migrations in a production environment with zero downtime?",
      "back": "Use an additive-only strategy: apply changes in multiple steps (e.g., add new column, sync data, update code to write to both, update code to read from new, drop old column). Avoid destructive operations like renaming columns directly.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the 'Outbox Pattern' in event-driven architectures?",
      "back": "It ensures atomicity between database updates and event publishing. You write the event to an 'outbox' table in the same transaction as your business logic, then a separate process polls the outbox to publish to Kafka/NATS.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "How do you approach mentoring a junior engineer who is struggling with technical tasks?",
      "back": "Focus on breaking down the problem into smaller, manageable chunks. Encourage them to explain their thought process, provide constructive feedback on their code, and guide them toward resources rather than solving the problem for them.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What are the common pitfalls when managing Node.js event loop performance?",
      "back": "Blocking the event loop with CPU-intensive synchronous operations. Use worker threads for heavy computation, ensure I/O is non-blocking, and monitor event loop lag to detect performance degradation.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the difference between a 'Read Committed' and 'Serializable' isolation level in PostgreSQL?",
      "back": "Read Committed prevents dirty reads but allows non-repeatable reads. Serializable is the strictest level, preventing all phenomena (dirty, non-repeatable, phantom reads) by simulating serial execution, though it may trigger serialization failures requiring application-level retries.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you handle 'poison pill' messages in a Kafka consumer?",
      "back": "Implement a Dead Letter Queue (DLQ). When a message fails processing after a set number of retries, move it to a separate topic for manual inspection or automated alerting, allowing the main consumer to continue processing.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "What is the purpose of Terraform state files?",
      "back": "They map real-world resources to your configuration, track metadata, and improve performance for large infrastructures. They must be stored remotely (e.g., S3 with locking) to allow team collaboration and prevent concurrent modification conflicts.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is a 'sidecar' container in Kubernetes?",
      "back": "A helper container running in the same pod as the main application container. It shares the same network namespace and storage volumes, typically used for logging, monitoring, or proxying traffic (e.g., service mesh).",
      "requirement_ids": ["r7"]
    },
    {
      "front": "How do you design a REST API to be backward compatible?",
      "back": "Never remove fields; only add them. Use versioning (URL path or headers) for breaking changes. Use optional fields for requests and ensure clients are robust enough to ignore unknown response fields.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the most important practice for effective on-call rotations?",
      "back": "Focus on actionable alerting. Reduce noise by tuning thresholds, ensure every alert has a clear runbook, and prioritize post-mortems to address the root cause of recurring incidents.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "In a logistics system, how do you handle idempotency for order creation?",
      "back": "Require a unique 'idempotency-key' from the client. Store this key in the database with a unique constraint. If a request with a duplicate key arrives, return the cached result of the original operation instead of re-processing.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "How do you balance technical debt with feature delivery?",
      "back": "Treat technical debt as a business risk. Quantify the impact (e.g., slower velocity, outages) and negotiate 'debt repayment' time into the sprint cycle, framing it as an investment in future stability and speed.",
      "requirement_ids": ["r1"]
    }
  ]
}
